<?php $galleryEntries=array_values(array_filter($settings['media'],fn($entry)=>($entry['section']??'')==='gallery'&&($entry['kind']??'image')==='image'));if($galleryEntries):?>
<section id="gallery" class="estate-gallery"><p class="eyebrow"><?=me(__('manor.gallery_eyebrow'))?></p><h2><?=me($settings['gallery_title'])?></h2><p><?=me($settings['gallery_text'])?></p><div class="estate-photo-grid"><?php foreach($galleryEntries as $entry):?><figure><a href="<?=me($entry['url'])?>" data-gallery-open data-caption="<?=me($entry['alt']??'')?>" aria-label="<?=me(__('manor.enlarge_photo').' '.($entry['alt']??''))?>"><img src="<?=me($entry['url'])?>" alt="<?=me($entry['alt']??'')?>" loading="lazy" decoding="async"></a><figcaption><?=me($entry['alt']??'')?></figcaption></figure><?php endforeach?></div></section>
<?php endif?>
